/**
 * Replicate her Artifact MAIN-stat lookup
 * (Artifact.js:30-34 + StatTableArtifact.getValue, StatTable/Artifact.js:6-12):
 * the per-rarity row is 0-INDEXED by level; out-of-range (or unknown key) → 0.
 */
export function getMainStatValue(key: string, rarity: number, level: number): number {
  const row = mainstats[key]?.[rarity - 1];
  if (row === undefined) return 0;
  return level < row.length ? row[level]! : 0;
}

/**
 * Replicate her SUBSTAT snap (DbObjectSubstat.getPreciseValue, Substat.js:8-13):
 * an EXACT dictionary lookup keyed by the GOOD display value — `dict[value] ?? value`
 * with a falsy-`value` early-return. NOT rounding: a value absent from the dict (or an
 * unknown stat key) passes through unchanged. The numeric `value` is normalised via
 * `String(value)` to match her JS object-key coercion (e.g. 7.0 → "7", 2.7 → "2.7").
 */
export function getPreciseSubValue(key: string, value: number, rarity: number): number {
  if (!value) return value;
  const dict = substatPreciseValues[key]?.[rarity - 1];
  if (dict === undefined) return value;
  return dict[String(value)] ?? value;
}
